function almanacEntries(content,type,query=''){const defs=type==='zombie'?content.ZOMBIES:content.PLANTS;return Object.values(defs).map((d,i)=>({...d,type,label:type==='zombie'?(ZCN[d.id]||d.name):(CN[d.id]||d.name),behavior:type==='plant'?(UPGRADE_NOTES[d.id]||PLANT_NOTES[i]||[d.description,'请参考植物能力与地形要求'])[0]:ZOMBIE_BEHAVIOR[i],counter:type==='plant'?(UPGRADE_NOTES[d.id]||PLANT_NOTES[i]||[d.description,'请参考植物能力与地形要求'])[1]:ZOMBIE_COUNTERS[i]})).filter(d=>{const source=d.label+' '+d.name+' '+d.id+' '+d.description+' '+d.behavior+' '+d.counter;const translated=root.GameI18n?[d.label,d.description,d.behavior,d.counter].map(text=>root.GameI18n.t(text||'')).join(' '):'';return (source+' '+translated).toLowerCase().includes(query.trim().toLowerCase());});}

function clamp(n,a,b){return Math.max(a,Math.min(b,n));}
function escapeHTML(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function levelName(n){return Math.ceil(n/10)+'-'+((n-1)%10+1);}
function readJSON(storage,key){try{return JSON.parse(storage.getItem(key)||'null');}catch(_){if(storage.protect)storage.protect(key);return null;}}
function writeValue(storage,key,value){try{storage.setItem(key,value);return true;}catch(_){return false;}}
function validCampaign(c){return c&&Number.isInteger(c.unlockedLevel)&&c.unlockedLevel>=1&&c.unlockedLevel<=50&&Array.isArray(c.completed);}
function pickAction(hit,selected,shovel,mode){if(!hit)return null;if(hit.type==='coin'||hit.coinId!=null)return {type:'collectCoin',id:hit.id==null?hit.coinId:hit.id};if(hit.type==='sun'||hit.sunId!=null)return {type:'collect',id:hit.id==null?hit.sunId:hit.id};if(!Number.isInteger(hit.row)||!Number.isInteger(hit.col)||hit.row<0||hit.col<0||hit.col>8)return null;if(shovel)return {type:'shovel',row:hit.row,col:hit.col};if(mode==='whack'&&!selected)return {type:'whack',row:hit.row,col:hit.col};if(mode==='vase'&&!selected)return {type:'breakVase',row:hit.row,col:hit.col};return selected?{type:'plant',kind:selected,row:hit.row,col:hit.col}:null;}
const api={almanacEntries,SAVE_KEY,CAMPAIGN_KEY,SKILL_SAVE_KEY,SKILL_CAMPAIGN_KEY,modeKeys,readJSON,writeValue,validCampaign,pickAction,levelName,clamp};root.PVZUI=api;if(typeof module!=='undefined')module.exports=api;
