// Keep the current session playable when browser storage is blocked/full. Never
// replace an unreadable original slot merely because opening a menu saves state.
let persistentStorage;try{persistentStorage=root.localStorage;}catch(_){}
const sessionValues=new Map(),protectedSlots=new Set(),storageIssues=new Set();
const storage={
 getItem(key){if(sessionValues.has(key))return sessionValues.get(key);try{const value=persistentStorage.getItem(key);sessionValues.set(key,value);return value;}catch(_){storageIssues.add('read');return null;}},
 setItem(key,value){sessionValues.set(key,String(value));if(protectedSlots.has(key)){storageIssues.add('invalid');throw Error('Original save preserved');}try{persistentStorage.setItem(key,String(value));}catch(err){storageIssues.add('write');throw err;}},
 protect(key){protectedSlots.add(key);storageIssues.add('invalid');}
};
function storageMessage(){return storageIssues.has('invalid')?'原存档无法完整读取，已保留原文件；当前游戏只在本次页面内保存，请勿关闭页面。':storageIssues.size?'浏览器存储不可用或空间不足；本次页面仍可继续、选关和练习，请勿关闭页面。':'进度自动保存在当前浏览器';}
function updateStorageStatus(){const el=$('save-status');if(el){el.hidden=!storageIssues.size;setText('save-status',storageMessage());}}

