function loadModeSave(raw){try{const loaded=E.Game.load(JSON.stringify(raw));if((loaded.gameMode||'classic')!==gameMode)throw new Error('存档模式不匹配');const restored=loaded.state.campaign;if(validCampaign(campaign)){restored.unlockedLevel=Math.max(restored.unlockedLevel,campaign.unlockedLevel);restored.completed=Array.from(new Set([...restored.completed,...campaign.completed.filter(n=>Number.isInteger(n)&&n>=1&&n<=50)])).sort((a,b)=>a-b);restored.unlockedPlants=Array.from(new Set([...restored.unlockedPlants,...(Array.isArray(campaign.unlockedPlants)?campaign.unlockedPlants:[]).filter(id=>Object.prototype.hasOwnProperty.call(C.PLANTS,id))]));restored.shovelUnlocked=restored.shovelUnlocked||campaign.shovelUnlocked===true;}campaign=restored;return loaded;}catch(err){storage.protect(modeKeys(gameMode).save);updateStorageStatus();throw err;}}
