function selectSeed(id){if(game.state.phase!=='playing')return;if(id==='imitater'&&debug){showImitater('battle');return;}cannonAim=null;shovel=false;selected=selected===id?null:id;updateUI(true);}
function aimCannon(p){if(p.reload>0){toast('玉米加农炮装填中 · 还需 '+Math.ceil(p.reload)+' 秒');return;}selected=null;shovel=false;cannonAim={id:p.id,row:p.row,col:Math.min(8,p.col+4)};hoverCell={row:cannonAim.row,col:cannonAim.col};canvas.focus();updateUI(true);}
function fireCannon(row,col){if(!cannonAim)return;const id=cannonAim.id;if(action({type:'fireCob',id,row,col})){cannonAim=null;hoverCell=null;updateUI(true);}}
function showImitater(origin){imitaterOrigin=origin;cannonAim=null;const defs=(origin==='battle'?Object.values(C.PLANTS):game.availablePlants()).filter(p=>p.id!=='imitater'&&!p.upgradeFrom&&!UPGRADE_NOTES[p.id]);modal('imitater','<div class="eyebrow">IMITATER · 第二步</div><h1 id="dialog-title">模仿哪一种植物？</h1><p>模仿者使用独立卡槽与冷却，可与原植物同时携带。种下后约 3.2 秒变身。</p><div class="selection-grid">'+defs.map(p=>'<button class="seed-card" data-imitate="'+p.id+'"><span class="seed-name">'+escapeHTML(name(p.id))+'</span>'+portrait(p.id,'seed-icon')+'<span class="seed-cost">'+p.cost+'</span></button>').join('')+'</div><button class="button secondary" data-command="imitater-cancel">返回</button>');}
function chooseImitater(id){imitaterChoice=id;if(imitaterOrigin==='battle'){if(!action({type:'setImitater',kind:id}))return;selected='imitater';shovel=false;closeModal();}else{if(!seedChoices.includes('imitater'))seedChoices.push('imitater');prepare(true);updateChoices();}traySignature=null;updateUI(true);}
function continueSaved(){if(!rendererReady){toast(rendererMessage());return;}const raw=readJSON(storage,modeKeys(gameMode).save);let loaded=null;if(raw){try{loaded=loadModeSave(raw);}catch(_){toast('原存档无法完整读取；已保留原文件，按已有进度重新准备关卡');}}if(!loaded){createGame(campaign.unlockedLevel,false);prepare();return;}game=loaded;imitaterChoice=game.state.imitaterKind||'peashooter';debug=false;clearSelection();if(game.state.phase==='paused')action({type:'resume'},true);if(game.state.phase==='selection')prepare();else if(['won','lost'].includes(game.state.phase))result();else closeModal();lastTime=0;updateUI(true);}


const TRAINING_LABELS={ground:'地面',air:'空中',submerged:'水下',armor:'护甲'};
function isTraining(){return !!(debug&&game&&game.state.training&&game.state.training.active);}
function enterTraining(){
 if(!rendererReady){toast(rendererMessage());return;}
 if(isTraining()){if(game.state.phase==='paused')action({type:'resume'});$('training-panel').open=true;closeModal();return;}
 if(!debug){persist();normalSnapshot=JSON.parse(game.save());createGame(8,true);}
 if(action({type:'debugTraining',terrain:'day'})){clearSelection();closeModal();lastTime=0;buildTrainingControls();$('training-panel').open=true;for(const row of game.state.levelDef.activeRows)action({type:'debugDummy',row,col:6,count:1,state:'ground',hp:10000,armor:0});updateUI(true);toast('每路已放置 1 个静止木桩；下方可调整数量、护甲和地形');}
}
function buildTrainingControls(){
 const s=game.state;if(!isTraining())return;
 $('training-terrain').value=s.training.terrain;
 $('training-row').innerHTML='<option value="all">所有可用路线</option>'+s.levelDef.activeRows.map(row=>'<option value="'+row+'">第 '+(row+1)+' 路'+(s.levelDef.waterRows.includes(row)?' · 水路':'')+'</option>').join('');
 $('training-row').value='all';
}
function spawnTrainingDummies(){
 if(!isTraining())return;
 const s=game.state,state=$('training-state').value,count=+$('training-count').value,hp=+$('training-hp').value,col=+$('training-col').value,rowValue=$('training-row').value;
 if(!Number.isInteger(count)||count<1||count>20||!Number.isFinite(hp)||hp<1||hp>1000000){toast('每路数量须为 1–20，本体 HP 须为 1–1,000,000');return;}
 let rows=rowValue==='all'?s.levelDef.activeRows:[+rowValue];
 if(state==='submerged'){rows=rows.filter(row=>s.levelDef.waterRows.includes(row));if(!rows.length){toast('水下木桩需要泳池或浓雾的水路，请先切换地形');return;}}
 let spawned=0;for(const row of rows){const before=s.zombies.length;if(action({type:'debugDummy',row,col,count,state,hp,armor:1100}))spawned+=s.zombies.length-before;else break;}
 if(spawned)toast('已放置 '+spawned+' 个'+TRAINING_LABELS[state]+'静止木桩');updateUI(true);
}
function updateTrainingUI(force=false){
 const active=isTraining();$('training-panel').hidden=!active;if(!active)return;
 const s=game.state,t=s.training,dummies=s.zombies.filter(z=>z.dummy),alive=dummies.filter(z=>z.hp>0);
 setText('debug-status','DEBUG · 训练场 · 不写入冒险存档');setText('training-pause',s.phase==='playing'?'暂停实测':'继续实测');setText('training-readiness',rendererReady?(s.phase==='playing'?'实时运行 · 静止木桩，不自动出怪':'已暂停 · 可调整木桩后继续'):'Canvas 2D 未就绪 · 模拟已停止');
 setText('training-stats','存活 '+alive.length+' / '+dummies.length+' · 命中 '+(t.hits||0)+' · 累计伤害 '+Math.round(t.damage||0)+' · 击倒 '+(t.kills||0)+' · 拦截 '+(t.blockedShots||0));
 if(!force&&$('training-target-details').open===false)return;
 const html=dummies.map(z=>'<div class="target-stat"><b>#'+z.id+' '+(TRAINING_LABELS[z.dummyState]||'木桩')+' · 第 '+(z.row+1)+' 路</b><span>HP '+Math.ceil(Math.max(0,z.hp))+' / '+z.dummyMaxHp+' · 护甲 '+Math.ceil(Math.max(0,z.armor||0))+' / '+(z.dummyMaxArmor||0)+'</span><small>命中 '+(z.hits||0)+' · 伤害 '+Math.round(z.damageTaken||0)+'</small></div>').join('')||'<p>木桩已清空。可选择预设后点击“批量放置木桩”，或点击“一键放置示例木桩”。</p>';
 if($('training-targets').innerHTML!==html)$('training-targets').innerHTML=html;
}
function showPlantCatalog(){if(!debug)return;modal('catalog','<div class="eyebrow">DEBUG · COMPLETE PLANT CATALOG</div><h1 id="dialog-title">全部 '+Object.keys(C.PLANTS).length+' 种植物</h1><p>'+(!game.state.debug.allPlants?'当前仅查阅，不改变传送带或冒险解锁。':'点选即返回棋盘种植。')+'升级植物仍需原植物；白天蘑菇需要咖啡豆，水路需要睡莲，屋顶需要花盆。</p><div class="catalog-filters"><label class="form-field">搜索名称或能力<input id="plant-search" type="search" value="'+escapeHTML(plantQuery)+'" placeholder="例如：冰西瓜 / 升级 / coffee"></label><label class="form-field">类别<select id="plant-category"><option value="all">全部植物</option><option value="base">普通植物</option><option value="upgrade">升级植物</option><option value="mushroom">蘑菇</option><option value="water">水生植物</option><option value="imitater">模仿者</option></select></label></div><div class="catalog-meta"><b id="plant-count" role="status"></b><button class="button secondary compact" data-command="catalog-clear">清除筛选</button></div><p class="scroll-affordance">↓ 上下滚动浏览完整目录 · 当前打开目录时战斗暂停</p><div id="plant-list" class="almanac-grid plant-picker" tabindex="0" aria-label="全部植物选择，可上下滚动"></div><div class="modal-actions"><button class="button secondary" data-command="catalog-close">返回棋盘</button></div>');$('plant-category').value=plantCategory;renderPlantCatalog();}
function renderPlantCatalog(){const entries=almanacEntries(C,'plant',plantQuery).filter(p=>plantCategory==='all'||plantCategory==='base'&&!p.upgradeFrom&&p.id!=='imitater'||plantCategory==='upgrade'&&p.upgradeFrom||plantCategory==='mushroom'&&p.mushroom||plantCategory==='water'&&['lily-pad','tangle-kelp','sea-shroom','cattail'].includes(p.id)||plantCategory==='imitater'&&p.id==='imitater');setText('plant-count',entries.length+' / '+Object.keys(C.PLANTS).length+' 种 · '+(game.state.debug.allPlants?'自由选种':'仅查阅 · 传送带与解锁规则保留'));$('plant-list').innerHTML=entries.map(p=>'<button class="almanac-entry '+(selected===p.id?'selected':'')+'" aria-pressed="'+(selected===p.id)+'" data-catalog-plant="'+p.id+'">'+portrait(p.id,'almanac-portrait')+'<strong>'+escapeHTML(p.label)+(selected===p.id?' ✓ 已选':'')+'</strong><small>'+p.cost+' 阳光'+(p.upgradeFrom?' · 升级':'')+'</small>'+(p.upgradeFrom?'<small class="upgrade-prerequisite">'+escapeHTML(p.id==='cob-cannon'?'需相邻两株玉米投手':('需'+name(p.upgradeFrom)))+'</small>':'')+'</button>').join('')||'<p>没有匹配植物，请清除筛选。</p>';}
function debugAction(a){if(action(a))toast(a.type==='debugSpawn'?'已生成测试僵尸':a.type==='debugClear'?'已清除僵尸':'已推进自动波次');}
